{"command": "cat > /prediction.json << 'EOF'
{
    "/workspace/vllm-project/vllm/vllm/model_executor/layers/fused_moe/gpt_oss_triton_kernels_moe.py": {
        "triton_kernel_fused_experts": "def triton_kernel_fused_experts(\n    output_tensor: torch.Tensor,\n    hidden_states: torch.Tensor,\n    w1,  # Tensor or triton_kernels.Tensor\n    w2,  # Tensor or triton_kernels.Tensor\n    routing_data,  # RoutingData\n    gather_indx,  # GatherIndx\n    scatter_indx,  # ScatterIndx\n    topk: int,\n    activation: str = \"silu\",\n    quant_config: FusedMoEQuantConfig | None = None,\n    swiglu_alpha: float = 1.702,\n    swiglu_limit: float = 7.0,\n    apply_router_weight_on_input: bool = False,\n    global_num_experts: int = -1,\n    expert_map: torch.Tensor | None = None,\n    intermediate_cache: torch.Tensor | None = None,\n    a1q_scale: torch.Tensor | None = None,\n) -> torch.Tensor:\n    if quant_config is None:\n        quant_config = FUSED_MOE_UNQUANTIZED_CONFIG\n\n    # type check, uint8 means mxfp4\n    assert hidden_states.dtype == torch.bfloat16\n    assert quant_config.w1_bias is None or quant_config.w1_bias.dtype == torch.float32\n    assert quant_config.w2_bias is None or quant_config.w2_bias.dtype == torch.float32\n\n    # Shape check, only check non-mxfp4\n    assert hidden_states.shape[-1] == w1.shape[-2]\n    assert w2.shape[-1] == w1.shape[1]\n\n    E, _, N = w1.shape\n    M = hidden_states.shape[0]\n\n    if global_num_experts == -1:\n        global_num_experts = E\n\n    act = FusedActivation(\n        FnSpecs(\"swiglu\", triton_kernels.swiglu.swiglu_fn, (\"alpha\", \"limit\")),\n        (swiglu_alpha, swiglu_limit),\n        2,\n    )\n    gammas = routing_data.gate_scal if routing_data else None\n\n    # Use pre-allocated intermediate cache for first matmul_ogs with shape [M * topk, N // 2]\n    if intermediate_cache is None:\n        intermediate_cache = torch.empty(\n            (M * topk, N // 2), dtype=hidden_states.dtype, device=hidden_states.device\n        )\n\n    intermediate_cache1 = matmul_ogs(\n        hidden_states,\n        w1,\n        quant_config.w1_bias,\n        routing_data,\n        gather_indx=gather_indx,\n        precision_config=quant_config.w1_precision,\n        gammas=gammas if apply_router_weight_on_input else None,\n        fused_activation=act,\n        y=intermediate_cache,\n    )\n\n    # Add batch dimension to output buffer for second matmul_ogs (expects 3D output)\n    output_3d = output_tensor.unsqueeze(0)  # [1, M, K]\n\n    intermediate_cache3 = matmul_ogs(\n        intermediate_cache1,\n        w2,\n        quant_config.w2_bias,\n        routing_data,\n        scatter_indx=scatter_indx,\n        precision_config=quant_config.w2_precision,\n        gammas=None if apply_router_weight_on_input else gammas,\n        y=output_3d,\n    )\n    return intermediate_cache3"
    }
}
EOF"}

